package dev.kinesis.core.model

import dev.kinesis.core.math.Color
import dev.kinesis.core.math.Vec2

/**
 * The single catalogue of effects: ids, categories, display names (pt-BR and English), parameters, defaults and
 * ranges. Everything else derives from it — the [Effect] serializer, scene evaluation, the semantic validator,
 * the effect picker and property rows in the app, `schema/knsproj-v2.schema.json`, `tools/knsproj/effects.json`
 * (used by the Python validator) and the effects table in `docs/knsproj.md` (the last three are generated by
 * `RegistryArtifactsTest`; run the core tests with `KINESIS_UPDATE_FIXTURES=1` after editing this file).
 *
 * Every effect is procedural and deterministic: effects with randomness take an integer `seed`, and time-varying
 * effects depend only on the layer's local time.
 */

/** Categories shown in the "Add effect" screen, in this order. [ALL] lists every effect. */
enum class EffectCategory(val id: String, val namePt: String, val nameEn: String) {
    ALL("all", "Todos os efeitos", "All effects"),
    COLOR_LIGHT("colorLight", "Cor e luz", "Color & light"),
    BLUR_SHARPEN("blurSharpen", "Desfoque e nitidez", "Blur & sharpen"),
    DISTORT("distort", "Distorção", "Distort"),
    MOTION("motion", "Movimentar e transformar", "Move & transform"),
    STYLIZE("stylize", "Estilizar", "Stylize"),
    GLITCH("glitch", "Glitch", "Glitch"),
    DRAW_EDGES("drawEdges", "Desenho e borda", "Drawing & edges"),
    PROCEDURAL("procedural", "Procedimental", "Procedural"),
    KEYING("keying", "Fosco, máscara e chave", "Matte, mask & key"),
    TIME("time", "Tempo e transição", "Time & transition"),
    TEXT("text", "Texto", "Text"),
    UTILITY("utility", "Utilitário e expressão", "Utility & expression"),
}

/**
 * Entries of the effect picker that open an existing editor instead of adding an entry to `effects[]`
 * (masks, track mattes, transitions and text animators are separate parts of the format).
 */
enum class EffectShortcut(val id: String, val category: EffectCategory, val namePt: String, val nameEn: String) {
    MASK("mask", EffectCategory.KEYING, "Máscara", "Mask"),
    TRACK_MATTE("trackMatte", EffectCategory.KEYING, "Track matte", "Track matte"),
    TRANSITIONS("transitions", EffectCategory.TIME, "Transições de entrada e saída", "In and out transitions"),
    TEXT_ANIMATORS("textAnimators", EffectCategory.TEXT, "Animadores de texto", "Text animators"),
}

enum class ParamType(val id: String) {
    /** Animatable number. */
    NUMBER("number"),

    /** Animatable number rounded to an integer when evaluated (counts, seeds). */
    INTEGER("integer"),

    /** Animatable `#RRGGBB[AA]` colour. */
    COLOR("color"),

    /** Animatable `[x, y]` in pixels relative to the layer's origin (its pivot), in the layer's own space. */
    POINT("point"),

    /** Static on/off switch. */
    BOOLEAN("boolean"),

    /** Static choice among [EffectParam.choices]. */
    CHOICE("choice"),

    /** Static gradient stops `[{offset, color}]` (same format as `fill.gradient.stops`). */
    STOPS("stops"),
    ;

    val animatable: Boolean get() = this == NUMBER || this == INTEGER || this == COLOR || this == POINT
}

/** Unit used to display a parameter. [display] multiplies stored values (e.g. 0..1 shown as 0..100 %). */
enum class ParamUnit(val id: String, val symbol: String, val display: Float = 1f) {
    NONE("none", ""),
    PX("px", "px"),
    DEG("deg", "°"),
    PERCENT("percent", "%", 100f),
    MULTIPLIER("multiplier", "×"),
    SECONDS("seconds", "s"),
    HERTZ("hertz", "Hz"),
    FPS("fps", "fps"),
    DEG_PER_SECOND("degPerSecond", "°/s"),
    EV("ev", "EV"),
}

data class EffectChoice(val id: String, val namePt: String, val nameEn: String)

/**
 * One parameter. [min]/[max] are the valid range (values outside are clamped when rendering and reported as
 * `effect.range` by the validators); [sliderMin]/[sliderMax] are the comfortable range for the UI slider.
 * [visibleWhen] hides the parameter in the UI unless another (choice) parameter has the given value.
 */
data class EffectParam(
    val name: String,
    val type: ParamType,
    val labelPt: String,
    val labelEn: String,
    val default: Any,
    val min: Float? = null,
    val max: Float? = null,
    val sliderMin: Float? = null,
    val sliderMax: Float? = null,
    val unit: ParamUnit = ParamUnit.NONE,
    val choices: List<EffectChoice> = emptyList(),
    val visibleWhen: Pair<String, String>? = null,
) {
    val defaultFloat: Float get() = (default as Number).toFloat()
    val defaultColor: Color get() = default as Color
    val defaultPoint: Vec2 get() = default as Vec2
    val defaultBoolean: Boolean get() = default as Boolean
    val defaultChoice: String get() = default as String

    @Suppress("UNCHECKED_CAST")
    val defaultStops: List<GradientStop> get() = default as List<GradientStop>

    fun clamp(v: Float): Float {
        var x = v
        if (min != null && x < min) x = min
        if (max != null && x > max) x = max
        return x
    }

    /** True when a choice/boolean parameter can be shown given the effect's other values. */
    fun isVisible(choiceOf: (String) -> String): Boolean = visibleWhen?.let { (p, v) -> choiceOf(p) == v } ?: true
}

/** Where an effect produces a visible result. */
enum class EffectTarget { ANY, LAYER_3D }

data class EffectSpec(
    val id: String,
    val category: EffectCategory,
    val namePt: String,
    val nameEn: String,
    /** One sentence, used in the docs and the schema. */
    val descriptionPt: String,
    val descriptionEn: String,
    val params: List<EffectParam>,
    val target: EffectTarget = EffectTarget.ANY,
    /** Reads the composite of the layers below (see `Glass`). */
    val needsBackdrop: Boolean = false,
) {
    private val byName = params.associateBy { it.name }
    fun param(name: String): EffectParam = byName[name] ?: error("effect '$id' has no parameter '$name'")
    fun paramOrNull(name: String): EffectParam? = byName[name]
}

object EffectRegistry {
    /** Bumped when the rendering of an existing effect changes (invalidates cached previews). */
    const val VERSION = 1

    // ------------------------------------------------------------------ parameter builders

    private fun num(
        name: String, pt: String, en: String, default: Float, min: Float? = null, max: Float? = null,
        sliderMin: Float? = null, sliderMax: Float? = null, unit: ParamUnit = ParamUnit.NONE, visibleWhen: Pair<String, String>? = null,
    ) = EffectParam(name, ParamType.NUMBER, pt, en, default, min, max, sliderMin ?: min, sliderMax ?: max, unit, visibleWhen = visibleWhen)

    private fun int(name: String, pt: String, en: String, default: Int, min: Int, max: Int, visibleWhen: Pair<String, String>? = null) =
        EffectParam(name, ParamType.INTEGER, pt, en, default.toFloat(), min.toFloat(), max.toFloat(), min.toFloat(), max.toFloat(), visibleWhen = visibleWhen)

    private fun seed() = EffectParam("seed", ParamType.INTEGER, "Semente", "Seed", 0f, 0f, 99_999f, 0f, 100f)

    private fun color(name: String, pt: String, en: String, default: Color, visibleWhen: Pair<String, String>? = null) =
        EffectParam(name, ParamType.COLOR, pt, en, default, visibleWhen = visibleWhen)

    private fun point(name: String, pt: String, en: String, default: Vec2 = Vec2.ZERO) =
        EffectParam(name, ParamType.POINT, pt, en, default, sliderMin = -2000f, sliderMax = 2000f, unit = ParamUnit.PX)

    private fun bool(name: String, pt: String, en: String, default: Boolean) = EffectParam(name, ParamType.BOOLEAN, pt, en, default)

    private fun choice(name: String, pt: String, en: String, default: String, vararg choices: EffectChoice) =
        EffectParam(name, ParamType.CHOICE, pt, en, default, choices = choices.toList())

    private fun c(id: String, pt: String, en: String) = EffectChoice(id, pt, en)

    private fun amount(default: Float = 1f, pt: String = "Quantidade", en: String = "Amount") =
        num("amount", pt, en, default, 0f, 1f, unit = ParamUnit.PERCENT)

    private fun angle(name: String = "angle", default: Float = 0f, pt: String = "Ângulo", en: String = "Angle") =
        num(name, pt, en, default, -3600f, 3600f, 0f, 360f, ParamUnit.DEG)

    private fun px(name: String, pt: String, en: String, default: Float, max: Float, sliderMax: Float = max, min: Float = 0f, sliderMin: Float = min) =
        num(name, pt, en, default, min, max, sliderMin, sliderMax, ParamUnit.PX)

    private fun hz(name: String = "frequency", default: Float, pt: String = "Frequência", en: String = "Frequency", max: Float = 60f) =
        num(name, pt, en, default, 0f, max, 0f, minOf(max, 20f), ParamUnit.HERTZ)

    private fun phase() = num("phase", "Fase", "Phase", 0f, -3600f, 3600f, 0f, 360f, ParamUnit.DEG)

    /** Common parameters of the procedural generators. */
    private fun blendParams() = listOf(
        choice(
            "mode", "Modo", "Mode", "replace",
            c("replace", "Substituir", "Replace"), c("add", "Adicionar", "Add"), c("multiply", "Multiplicar", "Multiply"),
            c("screen", "Tela", "Screen"), c("overlay", "Sobrepor", "Overlay"),
        ),
        num("mix", "Mistura", "Mix", 1f, 0f, 1f, unit = ParamUnit.PERCENT),
    )

    private val GRAY = Color(0.5f, 0.5f, 0.5f)

