    private val byId = all.associateBy { it.id }

    fun get(id: String): EffectSpec? = byId[id]
    fun require(id: String): EffectSpec = byId[id] ?: throw IllegalArgumentException("unknown effect type '$id'")

    fun inCategory(category: EffectCategory): List<EffectSpec> =
        if (category == EffectCategory.ALL) all else all.filter { it.category == category }

    fun shortcuts(category: EffectCategory): List<EffectShortcut> =
        if (category == EffectCategory.ALL) emptyList() else EffectShortcut.entries.filter { it.category == category }

    init {
        require(byId.size == all.size) { "duplicate effect id" }
        for (s in all) {
            require(s.category != EffectCategory.ALL && s.category != EffectCategory.TEXT) { "${s.id}: invalid category" }
            for (p in s.params) {
                if (p.type == ParamType.CHOICE) require(p.choices.any { it.id == p.default }) { "${s.id}.${p.name}: default not a choice" }
                if (p.type == ParamType.NUMBER || p.type == ParamType.INTEGER) {
                    require(p.clamp(p.defaultFloat) == p.defaultFloat) { "${s.id}.${p.name}: default outside range" }
                }
                p.visibleWhen?.let { (other, value) ->
                    require(s.paramOrNull(other)?.choices?.any { it.id == value } == true) { "${s.id}.${p.name}: bad visibleWhen" }
                }
            }
        }
    }
